(block.kind==='flow' || block.kind==='cards') || (block.kind==='table' && s.id==='notes'))}<UsabilityDiagram diagram={block} number={s.id==='workflow'?1:s.id==='notes'?2:3} {lang}/>{:else if lesson.id==='AASE-M07-C04' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<DataValidationDiagram diagram={block} number={s.id==='problem'?1:s.id==='cases'?2:s.id==='implementation'?3:4} {lang}/>{:else if lesson.id==='AASE-M09-C04' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<TechnologyChangeDiagram diagram={block} number={s.id==='contracts'?1:s.id==='plan'?2:3} {lang}/>{:else if lesson.id==='AASE-M07-C06' && (block.kind==='cards'||block.kind==='flow'||(block.kind==='table'&&/^(圖|Figure) 3/.test(block.caption)))}<AgentReviewDiagram diagram={block} number={Number(block.caption.match(/[0-9]+/)![0])} {lang}/>{:else if lesson.id==='AASE-M09-C03' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<AcceptanceEvidenceDiagram diagram={block} {lang}/>{:else if lesson.id==='AASE-M07-C07' && (block.kind==='cards'||block.kind==='flow')}<DebuggingDiagram diagram={block} number={s.id==='analogy'?1:s.id==='bug'?2:s.id==='loop'?3:4} {lang}/>{:else if lesson.id==='AASE-M07-C03' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}{#if s.id==='behavior'}<VerticalSliceForm diagram={block} {lang}/>{:else}<VerticalSliceDiagram diagram={block} number={s.id==='slice'?1:3} {lang}/>{/if}{:else if lesson.id==='AASE-M08-C06' && block.kind==='flow'}<RegressionEvidenceDiagram diagram={block} {lang}/>{:else if lesson.id==='AASE-M06-C01' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<FlowArchitectureDiagram diagram={block} number={s.id==='analogy'?(block.kind==='flow'?1:2):s.id==='runtime'?(block.items.length===7?3:4):5} {lang}/>{:else if lesson.id==='AASE-M06-C03' && lesson.revision>=4 && block.kind==='cards'}<C4ViewsDiagram diagram={block} number={s.id==='analogy'?1:s.id==='definition'?2:s.id==='restaurant'?2+s.blocks.slice(0,blockIndex+1).filter(b=>b.kind==='cards').length:s.id==='containers'?6:7} {lang}/>{:else if lesson.id==='AASE-M08-C01' && (block.kind==='cards'||block.kind==='flow')}<VerificationEvidenceDiagram diagram={block} number={s.id==='layers'?1:s.id==='record'?2:3} {lang}/>{:else}{#if lesson.id==='AASE-M06-C06' && (block.kind==='cards'||block.kind==='flow')}<TlsBoundaryDiagram diagram={block} number={s.id==='channel'?1:s.id==='hops'?2:3} {lang}/>{:else if lesson.id==='AASE-M06-C05' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<SessionAccessDiagram diagram={block} number={s.id==='controls'?(block.items.length===4?1:2):3} {lang}/>{:else if lesson.id==='AASE-M07-C01' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<EnvironmentSetupDiagram diagram={block} number={s.id==='analogy'?1:s.id==='layers'?2:block.kind==='flow'?3:4} {lang}/>{:else if lesson.id==='AASE-M07-C05' && (block.kind==='cards'||block.kind==='flow')}<PreviewExportDiagram diagram={block} number={s.id==='risk'?1:2} {lang}/>{:else if lesson.id==='AASE-M06-C04'&&block.kind==='prose'}<AaseProse paragraphs={block.paragraphs.flatMap(p=>p.split('\n\n'))}/>{:else if lesson.id==='AASE-M06-C04'&&(block.kind==='flow'||block.kind==='cards'||s.id==='record'&&block.kind==='table')}<WebDataFlowDiagram diagram={block} number={s.id==='analogy'?1:s.id==='outcomes'?2:s.id==='streamlit'?3:4} {lang}/>{:else}{#if lesson.id==='AASE-M07-C02' && lesson.revision>=4 && (block.kind==='flow'||block.kind==='cards')}<TaskContractDiagram diagram={block} number={block.kind==='flow'?1:2} {lang}/>{:else if lesson.id==='AASE-M06-C02' && (block.kind==='architecture'||block.kind==='cards')}<SystemContextLessonDiagram diagram={block} number={s.id==='analogy'?1:s.id==='levels'?2:s.id==='banking'?3:4} {lang}/>{:else if lesson.id==='AASE-M05-C02' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<SpecificationDiagram diagram={block} number={s.id==='analogy'?1:s.id==='quality'?2:s.id==='examples'?3:s.id==='specification'?4:5} {lang}/>{:else if lesson.id==='AASE-M05-C05' && (block.kind==='flow'||block.kind==='cards')}<OpenSpecDiagram diagram={block} number={s.id==='artifacts'?1:2} {lang}/>{:else if lesson.id==='AASE-M05-C03' && (block.kind==='cards'||block.kind==='flow')}<AcceptanceDiagram diagram={block} number={s.id==='mechanism'?1:s.id==='examples'?2:3} {lang}/>{:else if lesson.id==='AASE-M05-C01' && block.kind==='flow'}<PromptSpecDiagram diagram={block} {lang}/>{:else if lesson.id==='AASE-M03-C03' && block.kind==='step' && ['workflow-stale','workflow-walkthrough'].includes(block.id??'')}<WorkflowExercises mode={block.id==='workflow-stale'?'stale':'walkthrough'} {lang}/>{:else if lesson.id==='AASE-M03-C03' && (block.kind==='cards'||block.kind==='flow')}<WorkflowDiagram diagram={block} number={s.id==='analogy'?1:s.id==='flow'?2:s.id==='stale-result'?3:s.id==='layers'?5:6} {lang}/>{:else if lesson.id==='AASE-M04-C05' && lesson.revision>=5 && block.kind==='cards'}<DisclosureStatesDiagram diagram={block} number={s.id==='states'?5:s.id==='changes'?6:s.blocks.slice(0,blockIndex+1).filter(b=>b.kind==='cards').length} {lang}/>{:else if lesson.id==='AASE-M04-C03' && block.kind==='step'}<section><h3 id={block.id}>{block.heading}</h3><AaseProse paragraphs={block.paragraphs}/>{#if block.code}<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable code needs keyboard access.) --><div class="code-region" role="region" aria-label={block.heading+' code'} tabindex="0" style="max-width:100%;overflow:auto"><pre style="max-width:none;overflow:visible;min-width:max-content"><code>{block.code}</code></pre></div>{/if}</section>{:else if lesson.id==='AASE-M04-C03' && (block.kind==='cards'||block.kind==='flow')}<InformationHierarchyDiagram diagram={block} number={s.id==='structure'?1:s.id==='navigation'?2:s.id==='compare'?3:s.id==='groups'?4:s.id==='order'?5:6} {lang}/>{:else if lesson.id==='AASE-M04-C04' && (block.kind==='cards'||block.kind==='flow')}<WireframeDiagram diagram={block} number={s.id==='analogy'?1:s.id==='states'?2:s.id==='transitions'?3:s.id==='annotation'?4:5} {lang}/>{:else if lesson.id==='AASE-M04-C06' && lesson.revision>=4 && (block.kind==='cards'||block.kind==='flow')}<RecoveryDiagram diagram={block} number={s.id==='recovery'?(s.blocks??[]).slice(0,blockIndex+1).filter(b=>b.kind==='cards').length:s.id==='access'?4:5} {lang}/>{:else if lesson.id==='AASE-M04-C02' && (block.kind==='cards'||block.kind==='flow')}<TaskAnalysisDiagram diagram={block} number={s.id==='goal'?1:s.id==='plans'?(blockIndex===0?2:3):s.id==='methods'?4:5} {lang}/>{:else if lesson.id==='AASE-M04-C01' && (block.kind==='cards'||block.kind==='flow')}<HciPerspectivesDiagram diagram={block} number={s.id==='analogy'?1:s.id==='three-lenses'?2:s.id==='quality'?3:4} {lang}/>{:else if lesson.id==='AASE-M03-C04' && (block.kind==='cards'||block.kind==='flow')}<MvpScopeDiagram diagram={block} number={s.id==='analogy'?1:2} {lang}/>{:else if lesson.id==='AASE-M03-C05' && (block.kind==='cards'||block.kind==='flow')}<SuccessEvidenceDiagram diagram={block} number={s.id==='evidence-chain'?1:s.id==='metrics'?2:s.id==='measure'?3:s.id==='assumptions'?4:s.id==='trace'?5:6} {lang}/>{:else if lesson.id==='AASE-M03-C02' && (block.kind==='cards'||block.kind==='flow')}<StakeholderInterviewDiagram diagram={block} number={s.id==='roadmap'?1:s.id==='evidence'?2:3} {lang}/>{:else if lesson.id==='AASE-M03-C01' && (block.kind==='cards'||block.kind==='flow')}<ProblemStatementDiagram diagram={block} number={s.id==='analogy'?1:s.id==='structure'?2:s.id==='acceptance'?3:s.id==='workflow'?4:s.id==='documents'?(blockIndex===0?5:6):7} {lang}/>{:else if lesson.id==='AASE-M02-C06' && (block.kind==='cards'||block.kind==='flow')}<ToolEvidenceDiagram diagram={block} number={s.id==='analogy'?1:s.id==='sandbox'?2:s.id==='connection'?3:4} {lang}/>{:else if lesson.id==='AASE-M02-C05' && (block.kind==='cards'||block.kind==='flow')}<HarnessDiagram diagram={block} number={s.id==='analogy'?1:s.id==='six-aspects'?(blockIndex===0?2:3):4} {lang}/>{:else if lesson.id==='AASE-M02-C04' && (block.kind==='cards'||block.kind==='flow')}<AgentControlDiagram diagram={block} number={s.id==='control'?(block.items.length===4?1:2):s.id==='stopping'?3:4} {lang}/>{:else if lesson.id==='AASE-M02-C03' && (block.kind==='cards'||block.kind==='flow')}<MemoryMechanismsDiagram diagram={block} number={s.id==='office'?1:s.id==='kv-cache'?2:s.id==='summary-and-notes'?3:s.id==='retrieval'?4:s.id==='memory'?5:6} {lang}/>{:else if lesson.id==='AASE-M02-C02' && (block.kind==='cards'||block.kind==='flow')}<ContextWindowDiagram diagram={block} number={s.id==='analogy'?1:s.id==='window'?2:s.id==='budget-example'?3:block.kind==='cards'?4:5} {lang}/>{:else if lesson.id==='AASE-M02-C01' && (block.kind==='cards'||block.kind==='flow')}<TokenAttentionDiagram diagram={block} number={s.id==='pipeline'?1:s.id==='units'?2:s.id==='analogy'?3:s.id==='attention'?4:s.id==='attention-example'?5:6} {lang}/>{:else if lesson.id==='AASE-M01-C04' && (block.kind==='cards' || block.kind==='flow') && ['analogy','workflow','testing'].includes(s.id)}<RequirementsInterviewDiagram diagram={block} layout={s.id==='analogy'?'comparison':s.id==='workflow'?'process':'evidence'} {lang}/>{:else if lesson.id==='AASE-M01-C03' && s.id==='differences' && block.kind==='cards'}<OrganizationDimensions diagram={block}/>{:else if lesson.id==='AASE-M01-C03' && s.id==='identity' && block.kind==='cards'}<DocumentAccessSimulation diagram={block} {lang}/>{:else if lesson.id==='AASE-M01-C01' && s.id==='analogy' && block.kind==='cards'}<ApplicationCheckDemo comparison={block} {lang}/>{:else if lesson.id==='AASE-M05-C04' && block.kind==='flow'}<SddChangeDiagram diagram={block} {lang}/>{:else}<AaseBlocks blocks={[block]} {lang}/>{/if}{/if}{/if}{/each}{/if}{#if lesson.id==='AASE-M01-C01' && s.id==='scenario'}<ApplicationCheckDemo {lang}/>{/if}{#if lesson.id==='AASE-M01-C02' && s.id==='testing'}<AgentTestScenarios {lang}/>