<section><h2 id="practice">{l.practice}</h2><p>{l.environment}：{text.exercise.environment}</p><ol>{#each text.exercise.steps as step}<li>{step}</li>{/each}</ol><h3>{l.expected}</h3><p>{text.exercise.expected}</p><h3>{l.check}</h3><p>{text.exercise.check}</p><h3>{l.cleanup}</h3><p>{text.exercise.cleanup}</p></section>
<section><h2 id="checks">{l.checks}</h2><p>{l.checkIntro}</p>{#each lesson.checks as q}{@const t=q.text[lang]!}<section><h3 id={q.id}>{t.prompt}</h3><ol type="A">{#each t.options as option}<li>{option}</li>{/each}</ol><details><summary>{l.answerSummary}</summary><p>{l.answer}：{String.fromCharCode(65+q.answer)}</p><ol type="A">{#each t.rationales as reason}<li>{reason}</li>{/each}</ol></details></section>{/each}{#each text.openChecks??[] as q}{@const promptLines=['AASE-M04-C01','AASE-M06-C02'].includes(lesson.id)?q.prompt.split('\n'):[q.prompt]}<section><h3 id={q.id}>{promptLines[0]}</h3>{#if promptLines.length>1}<ol type="A">{#each promptLines.slice(1) as option}<li>{option}</li>{/each}</ol>{/if}<details><summary>{l.answerSummary}</summary>{#each q.answer as p}<p>{p}</p>{/each}</details></section>{/each}</section>
<section><h2 id="sources">{l.sources}</h2><p>{l.sourceIntro}</p><ul>{#each sources as source}<li><a href={source.url}>{source.title}</a> · {l.checked} <time datetime={source.checkedOn}>{source.checkedOn}</time></li>{/each}</ul><p><a href={localized('/courses/aase/v1/workshop/',lang)}>{l.workshop}</a></p></section>
